import{_ as n,o as t,c as r,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/unterricht-kataloge/kataloge-entlassungs-bemerkungen.png",h=JSON.parse('{"title":"Entlassungsbemerkungen im Katalog pflegen","description":"","frontmatter":{"title":"Entlassungsbemerkungen im Katalog pflegen","source_pageid":369,"source_revision":4677},"headers":[],"relativePath":"schild3/unterricht-kataloge/entlassungs-bemerkungen-allgemeine-kataloge.md","filePath":"schild3/unterricht-kataloge/entlassungs-bemerkungen-allgemeine-kataloge.md"}'),l={name:"schild3/unterricht-kataloge/entlassungs-bemerkungen-allgemeine-kataloge.md"};function i(g,e,o,u,m,d){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="entlassungsbemerkungen-im-katalog-pflegen" tabindex="-1">Entlassungsbemerkungen im Katalog pflegen <a class="header-anchor" href="#entlassungsbemerkungen-im-katalog-pflegen" aria-label="Permalink to &quot;Entlassungsbemerkungen im Katalog pflegen&quot;">​</a></h1><p>Bereiten Sie die Bemerkungen und Entlassgründe vor, die unter Schulbesuch verwendet werden sollen. Häufig benötigte Einträge können Sie nach oben sortieren.</p><p><a href="/bilder/unterricht-kataloge/kataloge-entlassungs-bemerkungen.png"><img src="'+s+'" alt="Über diesen Katalog lassen sich Entlassbemerkungen setzen." loading="lazy"></a></p><p><em>Über diesen Katalog lassen sich <strong>Entlassbemerkungen</strong> setzen.</em></p><p>Die in diesem Katalog zur Verfügung stehenden Einträge können auf der Registerkarte <em>Schüler ➜ Schulbesuch</em> im Bereich <em>Entlassung von eigener Schule</em> im Feld <strong>Bemerkung/Entlassgrund</strong> angewendet werden.</p><p>Sollten sie weitere Einträge ergänzen wollen - wie zum Beispiel <em>&quot;Bildungsabbruch&quot;</em> an den BKs, ... - erreichen Sie dies durch Anklicken des Plus <strong>+</strong>.</p><p>Eine benutzerdefinierte Sortierreihenfolge kann durch Wechsel auf <em>Benutzerdefiniert</em> in der Schaltfläche <em>Sortierung</em> erfolgen.</p><p>Verschieben Sie hierzu mit Hilfe der Pfeile am linken Rand Ihre Favoriten nach oben.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Entlassungs-Bemerkungen_(Allgemeine_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4677.</p>',10)])])}const k=n(l,[["render",i]]);export{h as __pageData,k as default};
